insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (36, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいにち <u>水泳</u>を します。', '["すいえい","けんどう","けんこう","きもち"]'::jsonb, 0, '水泳 dibaca “すいえい” dan berarti renang.', 'Bab 36–40 · Mondai 1 No.1', 'kanji:水泳'),
  (36, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつが <u>届きます</u>。', '["とどきます","はこびます","とびます","すぎます"]'::jsonb, 0, '届きます dibaca “とどきます” dan berarti sampai (barang).', 'Bab 36–40 · Mondai 1 No.2', 'kanji:届きます'),
  (36, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この にくは <u>硬い</u>です。', '["かたい","やわらかい","あんぜんな","とくべつな"]'::jsonb, 0, '硬い dibaca “かたい” dan berarti keras.', 'Bab 36–40 · Mondai 1 No.3', 'kanji:硬い'),
  (36, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいに <u>褒められました</u>。', '["ほめられました","しかられました","さそわれました","たのまれました"]'::jsonb, 0, '褒められました dibaca “ほめられました” dan berarti dipuji.', 'Bab 36–40 · Mondai 1 No.4', 'kanji:褒めます'),
  (36, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>招待します</u>。', '["しょうたいします","ちゅういします","たのみます","さそいます"]'::jsonb, 0, '招待します dibaca “しょうたいします” dan berarti mengundang.', 'Bab 36–40 · Mondai 1 No.5', 'kanji:招待します'),
  (36, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この きかいは <u>技術</u>が ひつようです。', '["ぎじゅつ","とち","そうおん","なかま"]'::jsonb, 0, '技術 dibaca “ぎじゅつ” dan berarti teknik/teknologi.', 'Bab 36–40 · Mondai 1 No.6', 'kanji:技術'),
  (36, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもを <u>育てます</u>。', '["そだてます","はこびます","せわをします","せいりします"]'::jsonb, 0, '育てます dibaca “そだてます” dan berarti membesarkan.', 'Bab 36–40 · Mondai 1 No.7', 'kanji:育てます'),
  (36, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おばあさんが <u>亡くなりました</u>。', '["なくなりました","にゅういんしました","たいいんしました","せいりしました"]'::jsonb, 0, '亡くなりました dibaca “なくなりました” dan berarti meninggal.', 'Bab 36–40 · Mondai 1 No.8', 'kanji:亡くなります'),
  (36, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しつもんに <u>答えます</u>。', '["こたえます","とおります","あんしんします","ちこくします"]'::jsonb, 0, '答えます dibaca “こたえます” dan berarti menjawab.', 'Bab 36–40 · Mondai 1 No.9', 'kanji:答えます'),
  (36, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'じしんで いえが <u>倒れました</u>。', '["たおれました","やけました","しにました","こしょうしました"]'::jsonb, 0, '倒れました dibaca “たおれました” dan berarti roboh.', 'Bab 36–40 · Mondai 1 No.10', 'kanji:倒れます'),
  (36, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいにち <u>けんこう</u>に きを つけます。', '["健康","気持ち","特別","安全"]'::jsonb, 0, 'けんこう ditulis 健康, berarti kesehatan.', 'Bab 36–40 · Mondai 2 No.11', 'kanji:健康'),
  (36, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを とおくまで <u>はこびます</u>。', '["運びます","飛びます","届きます","過ぎます"]'::jsonb, 0, 'はこびます ditulis 運びます, berarti mengangkut.', 'Bab 36–40 · Mondai 2 No.12', 'kanji:運びます'),
  (36, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'がいこくに しなものを <u>ゆしゅつします</u>。', '["輸出します","輸入します","翻訳します","発明します"]'::jsonb, 0, 'ゆしゅつします ditulis 輸出します, berarti mengekspor.', 'Bab 36–40 · Mondai 2 No.13', 'kanji:輸出します'),
  (36, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたらしい きかいを <u>はつめいしました</u>。', '["発明しました","発見しました","設計しました","翻訳しました"]'::jsonb, 0, 'はつめいしました ditulis 発明しました, berarti menciptakan.', 'Bab 36–40 · Mondai 2 No.14', 'kanji:発明します'),
  (36, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この きょうだいは よく <u>にています</u>。', '["似ています","育てています","整理しています","世話しています"]'::jsonb, 0, 'にています ditulis 似ています, berarti mirip.', 'Bab 36–40 · Mondai 2 No.15', 'kanji:似ています'),
  (36, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この にんぎょうは <u>ふしぎな</u> かたちです。', '["不思議な","大好きな","大きな","小さな"]'::jsonb, 0, 'ふしぎな ditulis 不思議な, berarti aneh/luar biasa.', 'Bab 36–40 · Mondai 2 No.16', 'kanji:不思議な'),
  (36, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あめで でんしゃが <u>ちこくしました</u>。', '["遅刻しました","早退しました","離婚しました","安心しました"]'::jsonb, 0, 'ちこくしました ditulis 遅刻しました, berarti terlambat.', 'Bab 36–40 · Mondai 2 No.17', 'kanji:遅刻します'),
  (36, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にんずうを <u>かぞえます</u>。', '["数えます","測ります","確かめます","積みます"]'::jsonb, 0, 'かぞえます ditulis 数えます, berarti menghitung.', 'Bab 36–40 · Mondai 2 No.18', 'kanji:数えます'),
  (36, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょりを <u>はかります</u>。', '["測ります","確かめます","数えます","積みます"]'::jsonb, 0, 'はかります ditulis 測ります, berarti mengukur.', 'Bab 36–40 · Mondai 2 No.19', 'kanji:測ります'),
  (36, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃが <u>しゅっぱつします</u>。', '["出発します","到着します","休憩します","出席します"]'::jsonb, 0, 'しゅっぱつします ditulis 出発します, berarti berangkat.', 'Bab 36–40 · Mondai 2 No.20', 'kanji:出発します'),
  (36, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなせる</span><span class="arrange-chip"><b>②</b>にほんご</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>れんしゅうします。</span><span class="arrange-chip"><b>⑤</b>ように</span><span class="arrange-chip"><b>⑥</b>まいにち</span></div><small>Petunjuk arti: “Saya berlatih setiap hari agar bisa berbicara Jepang.”</small>', '["②→③→①→⑤→⑥→④","③→②→①→⑤→⑥→④","②→①→③→⑤→⑥→④","②→③→⑤→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ②にほんご→③が→①はなせる→⑤ように→⑥まいにち→④れんしゅうします。 が menandai objek dari kata kerja potensial はなせる, dipakai sebelum ように untuk menyatakan tujuan (Pel.36).', 'Bab 36–40 · Mondai 3 No.21', 'materi:book2:10:0'),
  (36, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>たべる</span><span class="arrange-chip"><b>②</b>まいにち</span><span class="arrange-chip"><b>③</b>ように</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>やさい</span><span class="arrange-chip"><b>⑥</b>しています。</span></div><small>Petunjuk arti: “Saya membiasakan makan sayur setiap hari.”</small>', '["②→⑤→④→①→③→⑥","⑤→②→④→①→③→⑥","②→④→⑤→①→③→⑥","②→⑤→①→④→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ②まいにち→⑤やさい→④を→①たべる→③ように→⑥しています。 を menandai objek sebelum Kata Kerja bentuk辞書形＋ようにしています untuk menyatakan pembiasaan (Pel.36).', 'Bab 36–40 · Mondai 3 No.22', 'materi:book2:10:0'),
  (36, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほめられました。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>せんせい</span></div><small>Petunjuk arti: “Saya dipuji oleh guru.”</small>', '["②→③→⑤→④→①","③→②→⑤→④→①","②→⑤→③→④→①","②→③→④→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③は→⑤せんせい→④に→①ほめられました。 に menandai pelaku tindakan dalam bentuk pasif, dipakai sebelum ほめられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.23', 'materi:book2:11:0'),
  (36, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きのう</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>ふられました。</span><span class="arrange-chip"><b>④</b>あめ</span></div><small>Petunjuk arti: “Kemarin saya kehujanan.”</small>', '["①→④→②→③","④→①→②→③","①→②→④→③","①→④→③→②"]'::jsonb, 0, 'Urutan yang benar: ①きのう→④あめ→②に→③ふられました。 に menandai penyebab dalam pasif gangguan（迷惑の受身）seperti ふられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.24', 'materi:book2:11:0'),
  (36, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しゃしん</span><span class="arrange-chip"><b>②</b>とられました。</span><span class="arrange-chip"><b>③</b>に</span><span class="arrange-chip"><b>④</b>ともだち</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Saya difoto oleh teman.”</small>', '["④→③→①→⑤→②","③→④→①→⑤→②","④→①→③→⑤→②","④→③→⑤→①→②"]'::jsonb, 0, 'Urutan yang benar: ④ともだち→③に→①しゃしん→⑤を→②とられました。 に menandai pelaku tindakan dalam bentuk pasif, kali ini bersama とられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.25', 'materi:book2:11:0'),
  (36, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>すきです。</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>うたう</span><span class="arrange-chip"><b>⑤</b>わたし</span><span class="arrange-chip"><b>⑥</b>は</span></div><small>Petunjuk arti: “Saya suka bernyanyi.”</small>', '["⑤→⑥→④→②→③→①","⑥→⑤→④→②→③→①","⑤→④→⑥→②→③→①","⑤→⑥→②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ⑤わたし→⑥は→④うたう→②の→③が→①すきです。 が menandai objek kesukaan setelah kata kerja dinominalkan dengan の (V辞書形のが) (Pel.38).', 'Bab 36–40 · Mondai 3 No.26', 'materi:book2:12:0'),
  (36, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>べんきょうする</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>にほんご</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>たのしいです。</span></div><small>Petunjuk arti: “Belajar bahasa Jepang menyenangkan.”</small>', '["④→⑤→②→①→③→⑥","⑤→④→②→①→③→⑥","④→②→⑤→①→③→⑥","④→⑤→①→②→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ④にほんご→⑤を→②べんきょうする→①の→③は→⑥たのしいです。 は menandai topik setelah kata kerja dinominalkan dengan の (V辞書形のは) (Pel.38).', 'Bab 36–40 · Mondai 3 No.27', 'materi:book2:12:0'),
  (36, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こども</span><span class="arrange-chip"><b>②</b>べんきょうさせます。</span><span class="arrange-chip"><b>③</b>はは</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Ibu menyuruh anak belajar.”</small>', '["③→⑤→①→④→②","⑤→③→①→④→②","③→①→⑤→④→②","③→⑤→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③はは→⑤は→①こども→④を→②べんきょうさせます。 を menandai pihak yang disuruh dalam bentuk kausatif untuk kata kerja intransitif seperti べんきょうさせます (Pel.39).', 'Bab 36–40 · Mondai 3 No.28', 'materi:book2:13:0'),
  (36, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はっぴょうさせました。</span><span class="arrange-chip"><b>②</b>せんせい</span><span class="arrange-chip"><b>③</b>に</span><span class="arrange-chip"><b>④</b>がくせい</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Guru membuat siswa presentasi.”</small>', '["②→⑤→④→③→①","⑤→②→④→③→①","②→④→⑤→③→①","②→⑤→③→④→①"]'::jsonb, 0, 'Urutan yang benar: ②せんせい→⑤は→④がくせい→③に→①はっぴょうさせました。 に menandai pihak yang disuruh dalam bentuk kausatif untuk kata kerja tertentu seperti はっぴょうさせました (Pel.39).', 'Bab 36–40 · Mondai 3 No.29', 'materi:book2:13:0'),
  (36, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いらっしゃいます。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>かいぎしつ</span><span class="arrange-chip"><b>⑤</b>しゃちょう</span></div><small>Petunjuk arti: “Presiden direktur ada di ruang rapat.”</small>', '["⑤→③→④→②→①","③→⑤→④→②→①","⑤→④→③→②→①","⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑤しゃちょう→③は→④かいぎしつ→②に→①いらっしゃいます。 に menandai tempat keberadaan bersama いらっしゃいます, bentuk hormat dari います (Pel.40).', 'Bab 36–40 · Mondai 3 No.30', 'materi:book2:14:0'),
  (36, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おなまえ</span><span class="arrange-chip"><b>②</b>こちら</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>おかきください。</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Silakan tulis nama Anda di sini.”</small>', '["②→⑤→①→③→④","⑤→②→①→③→④","②→①→⑤→③→④","②→⑤→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②こちら→⑤に→①おなまえ→③を→④おかきください。 Pola お＋Vます-stem＋ください dipakai untuk meminta lawan bicara melakukan sesuatu dengan hormat (Pel.40).', 'Bab 36–40 · Mondai 4 No.31', 'materi:book2:14:0'),
  (36, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>もう</span><span class="arrange-chip"><b>③</b>おかえりに</span><span class="arrange-chip"><b>④</b>なりました。</span><span class="arrange-chip"><b>⑤</b>せんせい</span></div><small>Petunjuk arti: “Guru sudah pulang.”</small>', '["⑤→①→②→③→④","①→⑤→②→③→④","⑤→②→①→③→④","⑤→①→③→②→④"]'::jsonb, 0, 'Urutan yang benar: ⑤せんせい→①は→②もう→③おかえりに→④なりました。 Pola お＋Vます-stem＋になります menyatakan tindakan orang yang dihormati dengan sopan (Pel.40).', 'Bab 36–40 · Mondai 4 No.32', 'materi:book2:14:0'),
  (36, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ください。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>さきに</span><span class="arrange-chip"><b>⑤</b>かえらせて</span></div><small>Petunjuk arti: “Izinkan saya pulang lebih dulu.”</small>', '["②→③→④→⑤→①","③→②→④→⑤→①","②→④→③→⑤→①","②→③→⑤→④→①"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③を→④さきに→⑤かえらせて→①ください。 Kata Kerja bentuk させてください dipakai untuk meminta izin melakukan sesuatu (Pel.39).', 'Bab 36–40 · Mondai 4 No.33', 'materi:book2:13:0'),
  (36, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ここ</span><span class="arrange-chip"><b>②</b>うみ</span><span class="arrange-chip"><b>③</b>から</span><span class="arrange-chip"><b>④</b>みえます。</span><span class="arrange-chip"><b>⑤</b>が</span></div><small>Petunjuk arti: “Dari sini laut terlihat.”</small>', '["①→③→②→⑤→④","③→①→②→⑤→④","①→②→③→⑤→④","①→③→⑤→②→④"]'::jsonb, 0, 'Urutan yang benar: ①ここ→③から→②うみ→⑤が→④みえます。 見えます menyatakan sesuatu terlihat secara alami, subjeknya ditandai が (Pel.38).', 'Bab 36–40 · Mondai 4 No.34', 'materi:book2:12:0'),
  (36, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ふられました。</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>かえる</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>とき</span><span class="arrange-chip"><b>⑦</b>は</span></div><small>Petunjuk arti: “Ketika pulang, saya kehujanan.”</small>', '["④→⑦→③→⑥→②→⑤→①","⑦→④→③→⑥→②→⑤→①","④→③→⑦→⑥→②→⑤→①","④→⑦→⑥→③→②→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ④わたし→⑦は→③かえる→⑥とき→②あめ→⑤に→①ふられました。 Bentuk pasif gangguan dapat digabung dengan とき untuk menyatakan kapan hal tidak menyenangkan itu terjadi (Pel.37).', 'Bab 36–40 · Mondai 4 No.35', 'materi:book2:11:0'),
  (36, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、まいにち　やさいを　たべるように　しています。でも、おかしは　たべないように　しています。<br><small>たべないように　しているものは、なんですか。</small>', '["やさい","おかし","にく","くだもの"]'::jsonb, 1, 'ようにしています menyatakan KEBIASAAN yang dijalankan (makan sayur), sedangkan ないようにしています menyatakan KEBIASAAN MENGHINDARI (tidak makan kue) — dua arah pembiasaan berlawanan (Pel.36).', 'Bab 36–40 · Soal Cerita No.36', 'materi:book2:10:0'),
  (36, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　せんせいに　ほめられました。でも、かえる　とき、あめに　ふられました。<br><small>「あめに　ふられました」は、どんな　きもちですか。</small>', '["うれしいきもち","こまったきもち","たのしいきもち","あんしんしたきもち"]'::jsonb, 1, 'Pasif gangguan（迷惑の受身）seperti「雨に降られました」menyatakan DAMPAK TIDAK MENYENANGKAN (kehujanan = merepotkan), berbeda dari pasif biasa seperti「ほめられました」yang bisa bermakna netral/positif (dipuji) (Pel.37).', 'Bab 36–40 · Soal Cerita No.37', 'materi:book2:11:0'),
  (36, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　うたうのが　すきです。にほんごを　べんきょうするのは　たのしいです。<br><small>「すき」な ことは、なんですか。</small>', '["うたうこと","べんきょうすること","にほんごのこと","たのしいこと"]'::jsonb, 0, '「うたうのがすきです」memakai のが untuk menyatakan KESUKAAN (menyanyi), berbeda dari「べんきょうするのはたのしいです」yang memakai のは untuk menjadikan kegiatan sebagai TOPIK kalimat biasa, bukan pernyataan suka (Pel.38).', 'Bab 36–40 · Soal Cerita No.38', 'materi:book2:12:0'),
  (36, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'せんせいは　がくせいに　ほんを　よませました。ちちは　わたしに　りょうりを　つくらせました。<br><small>りょうりを　つくったのは、だれですか。</small>', '["せんせい","がくせい","ちち","わたし"]'::jsonb, 3, 'Bentuk kausatif「ちちはわたしにりょうりをつくらせました」berarti ayah MENYURUH saya memasak, jadi yang benar-benar memasak adalah SAYA (わたし), bukan ayah (Pel.39).', 'Bab 36–40 · Soal Cerita No.39', 'materi:book2:13:0'),
  (36, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'しゃちょうは　かいぎしつに　いらっしゃいます。わたしは　じむしょに　います。<br><small>「いらっしゃいます」は、だれについて　いいますか。</small>', '["わたし","しゃちょう","せんせい","がくせい"]'::jsonb, 1, 'いらっしゃいます adalah bentuk HORMAT dari います, hanya dipakai untuk orang yang DIHORMATI (presiden direktur/atasan), bukan untuk diri sendiri (わたし tetap pakai います biasa) (Pel.40).', 'Bab 36–40 · Soal Cerita No.40', 'materi:book2:14:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (36, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいにち <u>水泳</u>を します。', '["すいえい","けんどう","けんこう","きもち"]'::jsonb, 0, '水泳 dibaca “すいえい” dan berarti renang.', 'Bab 36–40 · Mondai 1 No.1', 'kanji:水泳'),
  (36, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつが <u>届きます</u>。', '["とどきます","はこびます","とびます","すぎます"]'::jsonb, 0, '届きます dibaca “とどきます” dan berarti sampai (barang).', 'Bab 36–40 · Mondai 1 No.2', 'kanji:届きます'),
  (36, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この にくは <u>硬い</u>です。', '["かたい","やわらかい","あんぜんな","とくべつな"]'::jsonb, 0, '硬い dibaca “かたい” dan berarti keras.', 'Bab 36–40 · Mondai 1 No.3', 'kanji:硬い'),
  (36, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいに <u>褒められました</u>。', '["ほめられました","しかられました","さそわれました","たのまれました"]'::jsonb, 0, '褒められました dibaca “ほめられました” dan berarti dipuji.', 'Bab 36–40 · Mondai 1 No.4', 'kanji:褒めます'),
  (36, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>招待します</u>。', '["しょうたいします","ちゅういします","たのみます","さそいます"]'::jsonb, 0, '招待します dibaca “しょうたいします” dan berarti mengundang.', 'Bab 36–40 · Mondai 1 No.5', 'kanji:招待します'),
  (36, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この きかいは <u>技術</u>が ひつようです。', '["ぎじゅつ","とち","そうおん","なかま"]'::jsonb, 0, '技術 dibaca “ぎじゅつ” dan berarti teknik/teknologi.', 'Bab 36–40 · Mondai 1 No.6', 'kanji:技術'),
  (36, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもを <u>育てます</u>。', '["そだてます","はこびます","せわをします","せいりします"]'::jsonb, 0, '育てます dibaca “そだてます” dan berarti membesarkan.', 'Bab 36–40 · Mondai 1 No.7', 'kanji:育てます'),
  (36, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おばあさんが <u>亡くなりました</u>。', '["なくなりました","にゅういんしました","たいいんしました","せいりしました"]'::jsonb, 0, '亡くなりました dibaca “なくなりました” dan berarti meninggal.', 'Bab 36–40 · Mondai 1 No.8', 'kanji:亡くなります'),
  (36, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しつもんに <u>答えます</u>。', '["こたえます","とおります","あんしんします","ちこくします"]'::jsonb, 0, '答えます dibaca “こたえます” dan berarti menjawab.', 'Bab 36–40 · Mondai 1 No.9', 'kanji:答えます'),
  (36, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'じしんで いえが <u>倒れました</u>。', '["たおれました","やけました","しにました","こしょうしました"]'::jsonb, 0, '倒れました dibaca “たおれました” dan berarti roboh.', 'Bab 36–40 · Mondai 1 No.10', 'kanji:倒れます'),
  (36, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいにち <u>けんこう</u>に きを つけます。', '["健康","気持ち","特別","安全"]'::jsonb, 0, 'けんこう ditulis 健康, berarti kesehatan.', 'Bab 36–40 · Mondai 2 No.11', 'kanji:健康'),
  (36, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にもつを とおくまで <u>はこびます</u>。', '["運びます","飛びます","届きます","過ぎます"]'::jsonb, 0, 'はこびます ditulis 運びます, berarti mengangkut.', 'Bab 36–40 · Mondai 2 No.12', 'kanji:運びます'),
  (36, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'がいこくに しなものを <u>ゆしゅつします</u>。', '["輸出します","輸入します","翻訳します","発明します"]'::jsonb, 0, 'ゆしゅつします ditulis 輸出します, berarti mengekspor.', 'Bab 36–40 · Mondai 2 No.13', 'kanji:輸出します'),
  (36, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたらしい きかいを <u>はつめいしました</u>。', '["発明しました","発見しました","設計しました","翻訳しました"]'::jsonb, 0, 'はつめいしました ditulis 発明しました, berarti menciptakan.', 'Bab 36–40 · Mondai 2 No.14', 'kanji:発明します'),
  (36, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この きょうだいは よく <u>にています</u>。', '["似ています","育てています","整理しています","世話しています"]'::jsonb, 0, 'にています ditulis 似ています, berarti mirip.', 'Bab 36–40 · Mondai 2 No.15', 'kanji:似ています'),
  (36, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この にんぎょうは <u>ふしぎな</u> かたちです。', '["不思議な","大好きな","大きな","小さな"]'::jsonb, 0, 'ふしぎな ditulis 不思議な, berarti aneh/luar biasa.', 'Bab 36–40 · Mondai 2 No.16', 'kanji:不思議な'),
  (36, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あめで でんしゃが <u>ちこくしました</u>。', '["遅刻しました","早退しました","離婚しました","安心しました"]'::jsonb, 0, 'ちこくしました ditulis 遅刻しました, berarti terlambat.', 'Bab 36–40 · Mondai 2 No.17', 'kanji:遅刻します'),
  (36, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にんずうを <u>かぞえます</u>。', '["数えます","測ります","確かめます","積みます"]'::jsonb, 0, 'かぞえます ditulis 数えます, berarti menghitung.', 'Bab 36–40 · Mondai 2 No.18', 'kanji:数えます'),
  (36, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょりを <u>はかります</u>。', '["測ります","確かめます","数えます","積みます"]'::jsonb, 0, 'はかります ditulis 測ります, berarti mengukur.', 'Bab 36–40 · Mondai 2 No.19', 'kanji:測ります'),
  (36, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃが <u>しゅっぱつします</u>。', '["出発します","到着します","休憩します","出席します"]'::jsonb, 0, 'しゅっぱつします ditulis 出発します, berarti berangkat.', 'Bab 36–40 · Mondai 2 No.20', 'kanji:出発します'),
  (36, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなせる</span><span class="arrange-chip"><b>②</b>にほんご</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>れんしゅうします。</span><span class="arrange-chip"><b>⑤</b>ように</span><span class="arrange-chip"><b>⑥</b>まいにち</span></div><small>Petunjuk arti: “Saya berlatih setiap hari agar bisa berbicara Jepang.”</small>', '["②→③→①→⑤→⑥→④","③→②→①→⑤→⑥→④","②→①→③→⑤→⑥→④","②→③→⑤→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ②にほんご→③が→①はなせる→⑤ように→⑥まいにち→④れんしゅうします。 が menandai objek dari kata kerja potensial はなせる, dipakai sebelum ように untuk menyatakan tujuan (Pel.36).', 'Bab 36–40 · Mondai 3 No.21', 'materi:book2:10:0'),
  (36, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>たべる</span><span class="arrange-chip"><b>②</b>まいにち</span><span class="arrange-chip"><b>③</b>ように</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>やさい</span><span class="arrange-chip"><b>⑥</b>しています。</span></div><small>Petunjuk arti: “Saya membiasakan makan sayur setiap hari.”</small>', '["②→⑤→④→①→③→⑥","⑤→②→④→①→③→⑥","②→④→⑤→①→③→⑥","②→⑤→①→④→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ②まいにち→⑤やさい→④を→①たべる→③ように→⑥しています。 を menandai objek sebelum Kata Kerja bentuk辞書形＋ようにしています untuk menyatakan pembiasaan (Pel.36).', 'Bab 36–40 · Mondai 3 No.22', 'materi:book2:10:0'),
  (36, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ほめられました。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>せんせい</span></div><small>Petunjuk arti: “Saya dipuji oleh guru.”</small>', '["②→③→⑤→④→①","③→②→⑤→④→①","②→⑤→③→④→①","②→③→④→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③は→⑤せんせい→④に→①ほめられました。 に menandai pelaku tindakan dalam bentuk pasif, dipakai sebelum ほめられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.23', 'materi:book2:11:0'),
  (36, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きのう</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>ふられました。</span><span class="arrange-chip"><b>④</b>あめ</span></div><small>Petunjuk arti: “Kemarin saya kehujanan.”</small>', '["①→④→②→③","④→①→②→③","①→②→④→③","①→④→③→②"]'::jsonb, 0, 'Urutan yang benar: ①きのう→④あめ→②に→③ふられました。 に menandai penyebab dalam pasif gangguan（迷惑の受身）seperti ふられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.24', 'materi:book2:11:0'),
  (36, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しゃしん</span><span class="arrange-chip"><b>②</b>とられました。</span><span class="arrange-chip"><b>③</b>に</span><span class="arrange-chip"><b>④</b>ともだち</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Saya difoto oleh teman.”</small>', '["④→③→①→⑤→②","③→④→①→⑤→②","④→①→③→⑤→②","④→③→⑤→①→②"]'::jsonb, 0, 'Urutan yang benar: ④ともだち→③に→①しゃしん→⑤を→②とられました。 に menandai pelaku tindakan dalam bentuk pasif, kali ini bersama とられました (Pel.37).', 'Bab 36–40 · Mondai 3 No.25', 'materi:book2:11:0'),
  (36, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>すきです。</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>うたう</span><span class="arrange-chip"><b>⑤</b>わたし</span><span class="arrange-chip"><b>⑥</b>は</span></div><small>Petunjuk arti: “Saya suka bernyanyi.”</small>', '["⑤→⑥→④→②→③→①","⑥→⑤→④→②→③→①","⑤→④→⑥→②→③→①","⑤→⑥→②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ⑤わたし→⑥は→④うたう→②の→③が→①すきです。 が menandai objek kesukaan setelah kata kerja dinominalkan dengan の (V辞書形のが) (Pel.38).', 'Bab 36–40 · Mondai 3 No.26', 'materi:book2:12:0'),
  (36, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>べんきょうする</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>にほんご</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>たのしいです。</span></div><small>Petunjuk arti: “Belajar bahasa Jepang menyenangkan.”</small>', '["④→⑤→②→①→③→⑥","⑤→④→②→①→③→⑥","④→②→⑤→①→③→⑥","④→⑤→①→②→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ④にほんご→⑤を→②べんきょうする→①の→③は→⑥たのしいです。 は menandai topik setelah kata kerja dinominalkan dengan の (V辞書形のは) (Pel.38).', 'Bab 36–40 · Mondai 3 No.27', 'materi:book2:12:0'),
  (36, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こども</span><span class="arrange-chip"><b>②</b>べんきょうさせます。</span><span class="arrange-chip"><b>③</b>はは</span><span class="arrange-chip"><b>④</b>を</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Ibu menyuruh anak belajar.”</small>', '["③→⑤→①→④→②","⑤→③→①→④→②","③→①→⑤→④→②","③→⑤→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③はは→⑤は→①こども→④を→②べんきょうさせます。 を menandai pihak yang disuruh dalam bentuk kausatif untuk kata kerja intransitif seperti べんきょうさせます (Pel.39).', 'Bab 36–40 · Mondai 3 No.28', 'materi:book2:13:0'),
  (36, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はっぴょうさせました。</span><span class="arrange-chip"><b>②</b>せんせい</span><span class="arrange-chip"><b>③</b>に</span><span class="arrange-chip"><b>④</b>がくせい</span><span class="arrange-chip"><b>⑤</b>は</span></div><small>Petunjuk arti: “Guru membuat siswa presentasi.”</small>', '["②→⑤→④→③→①","⑤→②→④→③→①","②→④→⑤→③→①","②→⑤→③→④→①"]'::jsonb, 0, 'Urutan yang benar: ②せんせい→⑤は→④がくせい→③に→①はっぴょうさせました。 に menandai pihak yang disuruh dalam bentuk kausatif untuk kata kerja tertentu seperti はっぴょうさせました (Pel.39).', 'Bab 36–40 · Mondai 3 No.29', 'materi:book2:13:0'),
  (36, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>いらっしゃいます。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>かいぎしつ</span><span class="arrange-chip"><b>⑤</b>しゃちょう</span></div><small>Petunjuk arti: “Presiden direktur ada di ruang rapat.”</small>', '["⑤→③→④→②→①","③→⑤→④→②→①","⑤→④→③→②→①","⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑤しゃちょう→③は→④かいぎしつ→②に→①いらっしゃいます。 に menandai tempat keberadaan bersama いらっしゃいます, bentuk hormat dari います (Pel.40).', 'Bab 36–40 · Mondai 3 No.30', 'materi:book2:14:0'),
  (36, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おなまえ</span><span class="arrange-chip"><b>②</b>こちら</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>おかきください。</span><span class="arrange-chip"><b>⑤</b>に</span></div><small>Petunjuk arti: “Silakan tulis nama Anda di sini.”</small>', '["②→⑤→①→③→④","⑤→②→①→③→④","②→①→⑤→③→④","②→⑤→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②こちら→⑤に→①おなまえ→③を→④おかきください。 Pola お＋Vます-stem＋ください dipakai untuk meminta lawan bicara melakukan sesuatu dengan hormat (Pel.40).', 'Bab 36–40 · Mondai 4 No.31', 'materi:book2:14:0'),
  (36, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>もう</span><span class="arrange-chip"><b>③</b>おかえりに</span><span class="arrange-chip"><b>④</b>なりました。</span><span class="arrange-chip"><b>⑤</b>せんせい</span></div><small>Petunjuk arti: “Guru sudah pulang.”</small>', '["⑤→①→②→③→④","①→⑤→②→③→④","⑤→②→①→③→④","⑤→①→③→②→④"]'::jsonb, 0, 'Urutan yang benar: ⑤せんせい→①は→②もう→③おかえりに→④なりました。 Pola お＋Vます-stem＋になります menyatakan tindakan orang yang dihormati dengan sopan (Pel.40).', 'Bab 36–40 · Mondai 4 No.32', 'materi:book2:14:0'),
  (36, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ください。</span><span class="arrange-chip"><b>②</b>わたし</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>さきに</span><span class="arrange-chip"><b>⑤</b>かえらせて</span></div><small>Petunjuk arti: “Izinkan saya pulang lebih dulu.”</small>', '["②→③→④→⑤→①","③→②→④→⑤→①","②→④→③→⑤→①","②→③→⑤→④→①"]'::jsonb, 0, 'Urutan yang benar: ②わたし→③を→④さきに→⑤かえらせて→①ください。 Kata Kerja bentuk させてください dipakai untuk meminta izin melakukan sesuatu (Pel.39).', 'Bab 36–40 · Mondai 4 No.33', 'materi:book2:13:0'),
  (36, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ここ</span><span class="arrange-chip"><b>②</b>うみ</span><span class="arrange-chip"><b>③</b>から</span><span class="arrange-chip"><b>④</b>みえます。</span><span class="arrange-chip"><b>⑤</b>が</span></div><small>Petunjuk arti: “Dari sini laut terlihat.”</small>', '["①→③→②→⑤→④","③→①→②→⑤→④","①→②→③→⑤→④","①→③→⑤→②→④"]'::jsonb, 0, 'Urutan yang benar: ①ここ→③から→②うみ→⑤が→④みえます。 見えます menyatakan sesuatu terlihat secara alami, subjeknya ditandai が (Pel.38).', 'Bab 36–40 · Mondai 4 No.34', 'materi:book2:12:0'),
  (36, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ふられました。</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>かえる</span><span class="arrange-chip"><b>④</b>わたし</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>とき</span><span class="arrange-chip"><b>⑦</b>は</span></div><small>Petunjuk arti: “Ketika pulang, saya kehujanan.”</small>', '["④→⑦→③→⑥→②→⑤→①","⑦→④→③→⑥→②→⑤→①","④→③→⑦→⑥→②→⑤→①","④→⑦→⑥→③→②→⑤→①"]'::jsonb, 0, 'Urutan yang benar: ④わたし→⑦は→③かえる→⑥とき→②あめ→⑤に→①ふられました。 Bentuk pasif gangguan dapat digabung dengan とき untuk menyatakan kapan hal tidak menyenangkan itu terjadi (Pel.37).', 'Bab 36–40 · Mondai 4 No.35', 'materi:book2:11:0'),
  (36, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、まいにち　やさいを　たべるように　しています。でも、おかしは　たべないように　しています。<br><small>たべないように　しているものは、なんですか。</small>', '["やさい","おかし","にく","くだもの"]'::jsonb, 1, 'ようにしています menyatakan KEBIASAAN yang dijalankan (makan sayur), sedangkan ないようにしています menyatakan KEBIASAAN MENGHINDARI (tidak makan kue) — dua arah pembiasaan berlawanan (Pel.36).', 'Bab 36–40 · Soal Cerita No.36', 'materi:book2:10:0'),
  (36, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　せんせいに　ほめられました。でも、かえる　とき、あめに　ふられました。<br><small>「あめに　ふられました」は、どんな　きもちですか。</small>', '["うれしいきもち","こまったきもち","たのしいきもち","あんしんしたきもち"]'::jsonb, 1, 'Pasif gangguan（迷惑の受身）seperti「雨に降られました」menyatakan DAMPAK TIDAK MENYENANGKAN (kehujanan = merepotkan), berbeda dari pasif biasa seperti「ほめられました」yang bisa bermakna netral/positif (dipuji) (Pel.37).', 'Bab 36–40 · Soal Cerita No.37', 'materi:book2:11:0'),
  (36, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　うたうのが　すきです。にほんごを　べんきょうするのは　たのしいです。<br><small>「すき」な ことは、なんですか。</small>', '["うたうこと","べんきょうすること","にほんごのこと","たのしいこと"]'::jsonb, 0, '「うたうのがすきです」memakai のが untuk menyatakan KESUKAAN (menyanyi), berbeda dari「べんきょうするのはたのしいです」yang memakai のは untuk menjadikan kegiatan sebagai TOPIK kalimat biasa, bukan pernyataan suka (Pel.38).', 'Bab 36–40 · Soal Cerita No.38', 'materi:book2:12:0'),
  (36, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'せんせいは　がくせいに　ほんを　よませました。ちちは　わたしに　りょうりを　つくらせました。<br><small>りょうりを　つくったのは、だれですか。</small>', '["せんせい","がくせい","ちち","わたし"]'::jsonb, 3, 'Bentuk kausatif「ちちはわたしにりょうりをつくらせました」berarti ayah MENYURUH saya memasak, jadi yang benar-benar memasak adalah SAYA (わたし), bukan ayah (Pel.39).', 'Bab 36–40 · Soal Cerita No.39', 'materi:book2:13:0'),
  (36, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'しゃちょうは　かいぎしつに　いらっしゃいます。わたしは　じむしょに　います。<br><small>「いらっしゃいます」は、だれについて　いいますか。</small>', '["わたし","しゃちょう","せんせい","がくせい"]'::jsonb, 1, 'いらっしゃいます adalah bentuk HORMAT dari います, hanya dipakai untuk orang yang DIHORMATI (presiden direktur/atasan), bukan untuk diri sendiri (わたし tetap pakai います biasa) (Pel.40).', 'Bab 36–40 · Soal Cerita No.40', 'materi:book2:14:0');
